from __future__ import annotations

import asyncio
import logging
import threading
from datetime import datetime
from pathlib import Path
from typing import Any, Awaitable, Callable, List, Optional, Tuple, Union

try:
    from typing import Self
except ImportError:
    from typing_extensions import Self

from zk import ZK

from . import constants as consts
from .client import ZKClient
from .models import (
    AttendanceRecord,
    CapacityInfo,
    DeviceInfo,
    FingerprintTemplate,
    LiveAccessEvent,
    User,
)
from .rules import AccessRulesRegistry

logger = logging.getLogger("zk.async_client")


class AsyncZKClient:
    """
    Asynchronous Python client for ZKTeco standalone access control & time attendance devices.
    Executes blocking socket/pyzk calls in background threads via `asyncio.to_thread`
    with proper async concurrency locking, ensuring it never stalls the event loop of
    FastAPI, Celery, or aio-pika microservices.

    Usage::

        from zk import AsyncZKClient

        async with AsyncZKClient("192.168.1.201") as client:
            info = await client.get_info()
            print("Firmware:", info.firmware_version)

            users = await client.list_users()
            for u in users:
                print(u.user_id, u.name)
    """

    def __init__(
        self,
        ip: str,
        port: int = consts.DEFAULT_PORT,
        timeout: int = consts.DEFAULT_TIMEOUT,
        password: int = 0,
        force_udp: bool = True,
        ommit_ping: bool = False,
        use_sdk_build_1: bool = True,
        rules: Optional[AccessRulesRegistry] = None,
        rules_storage_path: Optional[Union[str, Path]] = None,
    ):
        self.ip = ip
        self.port = port
        self.timeout = timeout
        self.password = password
        self.force_udp = force_udp
        self.ommit_ping = ommit_ping
        self.use_sdk_build_1 = use_sdk_build_1

        self.rules = rules or AccessRulesRegistry(storage_path=rules_storage_path)

        self._lock = asyncio.Lock()
        self._sync_client: Optional[ZKClient] = None

        self._capture_thread: Optional[threading.Thread] = None
        self._capture_stop = threading.Event()

    def _get_sync_client(self) -> ZKClient:
        if self._sync_client is None:
            self._sync_client = ZKClient(
                ip=self.ip,
                port=self.port,
                timeout=self.timeout,
                password=self.password,
                force_udp=self.force_udp,
                ommit_ping=self.ommit_ping,
                use_sdk_build_1=self.use_sdk_build_1,
                rules=self.rules,
            )
        return self._sync_client

    async def __aenter__(self) -> Self:
        await self.connect()
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.disconnect()
        return False

    async def connect(self) -> None:
        """Connect to the device asynchronously."""
        async with self._lock:
            client = self._get_sync_client()
            await asyncio.to_thread(client.connect)

    async def disconnect(self) -> None:
        """Disconnect and cleanup background threads."""
        await self.stop_live_capture()
        async with self._lock:
            if self._sync_client:
                await asyncio.to_thread(self._sync_client.disconnect)
                self._sync_client = None

