    # ─── Async Real-Time Live Capture ──────────────────────────────────────────

    async def start_live_capture(
        self,
        on_event: Callable[[LiveAccessEvent], Union[None, Awaitable[None]]],
        on_tick: Optional[Callable[[], Union[None, Awaitable[None]]]] = None,
        enforce_rules: bool = False,
    ) -> None:
        """
        Start non-blocking real-time event capture running in a dedicated background thread.
        Events are dispatched back to the running event loop via async/sync callback.
        """
        if self._capture_thread and self._capture_thread.is_alive():
            logger.warning("Live capture is already running on %s", self.ip)
            return

        loop = asyncio.get_running_loop()
        self._capture_stop.clear()

        def _worker():
            worker_zk = ZK(
                self.ip,
                port=self.port,
                timeout=self.timeout,
                password=self.password,
                force_udp=self.force_udp,
                ommit_ping=self.ommit_ping,
            )
            conn = None
            try:
                conn = worker_zk.connect()
                conn.reg_event(consts.EVENT_REG_ALL)
                logger.info("Async live capture thread connected for %s", self.ip)

                for raw_att in conn.live_capture():
                    if self._capture_stop.is_set():
                        break

                    if raw_att is not None:
                        att = AttendanceRecord(
                            user_id=str(raw_att.user_id),
                            timestamp=raw_att.timestamp,
                            status=int(raw_att.status),
                            punch=int(raw_att.punch),
                            uid=getattr(raw_att, "uid", None),
                        )

                        allowed = None
                        area_name = None
                        verdict = None
                        if enforce_rules:
                            allowed = self.rules.is_access_allowed(
                                att.user_id, att.timestamp
                            )
                            area = self.rules.get_user_area(att.user_id)
                            area_name = area.name if area else None
                            verdict = (
                                "OK" if allowed else "ACCESS_DENIED_OUT_OF_SCHEDULE"
                            )

                        event = LiveAccessEvent(
                            attendance=att,
                            allowed=allowed,
                            area_name=area_name,
                            verdict=verdict,
                        )

                        if asyncio.iscoroutinefunction(on_event):
                            asyncio.run_coroutine_threadsafe(on_event(event), loop)
                        else:
                            loop.call_soon_threadsafe(on_event, event)

                    if on_tick:
                        if asyncio.iscoroutinefunction(on_tick):
                            asyncio.run_coroutine_threadsafe(on_tick(), loop)
                        else:
                            loop.call_soon_threadsafe(on_tick)

            except Exception as exc:
                if not self._capture_stop.is_set():
                    logger.error(
                        "Error in live capture thread for %s: %s", self.ip, exc
                    )
            finally:
                if conn:
                    try:
                        conn.end_live_capture = True
                        conn.enable_device()
                        conn.disconnect()
                    except Exception:
                        pass
                logger.info("Live capture thread exited for %s", self.ip)

        self._capture_thread = threading.Thread(
            target=_worker,
            name=f"zk-async-livecapture-{self.ip}",
            daemon=True,
        )
        self._capture_thread.start()

    async def stop_live_capture(self) -> None:
        """Stop background live capture thread."""
        self._capture_stop.set()
        if self._capture_thread and self._capture_thread.is_alive():
            await asyncio.to_thread(self._capture_thread.join, timeout=5.0)
            self._capture_thread = None

    def is_capturing(self) -> bool:
        return bool(self._capture_thread and self._capture_thread.is_alive())
